Verified: `Client` accepts an in-process `FastMCP` server object directly, and `read_resource` returns a list of `TextResourceContents | BlobResourceContents`.

```python
import asyncio

from fastmcp import FastMCP, Client

mcp = FastMCP("Demo Server")


@mcp.resource("data://config")
def get_config() -> dict:
    return {"debug": True, "version": "1.0"}


async def main() -> None:
    client = Client(mcp)

    async with client:
        contents = await client.read_resource("data://config")
        for content in contents:
            if hasattr(content, "text"):
                print(content.text)
            else:
                print(content.blob)


if __name__ == "__main__":
    asyncio.run(main())
